@startuml

class Animal {
  + ID : int
  + Name : string
  + Breed : string
}

class Owner {
  + ID : int
  + Name : string
  + Address : string
  + Phone : string
}

class Breed {
  + Name : string
}

class Physician {
  + ID : int
  + Name : string
  + Address : string
  + Phone : string
}

class Appointment {
  + StartDateTime : datetime
}

class Condition {
  + CommonName : string
  + ScientificName : string
}

Owner "0..1" -- "*" Animal : owns
Animal "*" -- "1" Breed : belongsTo
Physician "1" -- "*" Appointment : is responsible for
Animal "1" -- "*" Appointment : attends
Owner "1" -- "*" Appointment : attends
Breed "*" -- "*" Condition : commonly has

